package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                       // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.New(0, 0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.New(0, 0)      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.New(0, 0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                            // PIC 9(3) len=3 = 0
var WsPriceEd string                             // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string                              // PIC ZZ,ZZ9.99 len=9
var WsNetEd string                               // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string                             // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec DiscRec
var hasRec bool
var discLines []string
var discIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone() {
	WsEofFlag = "Y"
}

func parsePrice(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	// s contains digits only, maybe spaces
	// keep only digits and sign
	// COBOL numeric display fields are digits
	n := int64(0)
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return decimal.New(n, -2)
}

func parseIntField(s string, width int) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var n int64
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return n
}

func storePIC(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	truncated := value.Truncate(scale)
	scaled := truncated.Shift(scale).Truncate(0)
	total := intDigits + int(scale)
	mod := decimal.New(1, int32(total))
	sign := scaled.Sign()
	abs := scaled.Abs()
	storedAbs := abs.Mod(mod)
	if sign < 0 {
		storedAbs = storedAbs.Neg()
	}
	return storedAbs.Shift(-scale)
}

func formatEdited(value decimal.Decimal, picture string) string {
	// count scale
	dotPos := strings.Index(picture, ".")
	scale := 0
	intPic := picture
	if dotPos >= 0 {
		scale = len(picture) - dotPos - 1
		intPic = picture[:dotPos]
	}
	// count int slots
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	tenPowScale := decimal.New(1, int32(scale))
	tenPowInt := decimal.New(1, int32(intSlots))

	absVal := value.Abs()
	scaled := absVal.Shift(int32(scale)).Truncate(0)
	intPartAll := scaled.Div(tenPowScale).Truncate(0)
	fracPart := scaled.Mod(tenPowScale)
	intPartMod := intPartAll.Mod(tenPowInt)

	intStr := intPartMod.StringFixed(0)
	// pad leading zeros to intSlots
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	} else if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	fracStr := fracPart.StringFixed(0)
	if len(fracStr) < scale {
		fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
	} else if len(fracStr) > scale {
		fracStr = fracStr[len(fracStr)-scale:]
	}

	// build result skeleton
	res := []rune(picture)
	// fill integer digits
	digitIdx := 0
	for i, ch := range picture {
		if dotPos >= 0 && i > dotPos {
			break
		}
		if dotPos >= 0 && i == dotPos {
			res[i] = '.'
			continue
		}
		if ch == 'Z' || ch == '9' {
			if digitIdx < len(intStr) {
				res[i] = rune(intStr[digitIdx])
				digitIdx++
			} else {
				res[i] = '0'
			}
		} else if ch == ',' {
			res[i] = ','
		} else if ch == '.' {
			res[i] = '.'
		}
	}
	// fill fractional digits after dot
	if dotPos >= 0 {
		for i := dotPos + 1; i < len(picture); i++ {
			fIdx := i - dotPos - 1
			if fIdx < len(fracStr) {
				res[i] = rune(fracStr[fIdx])
			}
		}
	}

	// Z suppression for integer part
	// Determine suppressed flag: true until a non-zero digit encountered
	suppressed := true
	// we need to walk left to right over integer section including commas
	endInt := len(picture)
	if dotPos >= 0 {
		endInt = dotPos
	}
	for i := 0; i < endInt; i++ {
		pch := picture[i]
		if pch == 'Z' || pch == '9' {
			d := res[i]
			if suppressed {
				if d != '0' {
					suppressed = false
					// keep d
				} else {
					if pch == 'Z' {
						res[i] = ' '
						// stay suppressed
					} else {
						// '9' with zero stays '0', stay suppressed for comma purposes
						// keep '0'
					}
				}
			} else {
				// already unsuppressed, keep
			}
		} else if pch == ',' {
			if suppressed {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		}
	}
	return string(res)
}

func loadDiscFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file => empty
		discLines = []string{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// remove trailing \r if present (Scanner already strips \n, but not \r)
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		// keep as is; padding will be done on parse
		discLines = append(discLines, line)
	}
}

func READ_PARA() {
	if discIdx >= len(discLines) {
		setInputDone()
		hasRec = false
		return
	}
	raw := discLines[discIdx]
	discIdx++
	// pad to 15 with spaces on the right
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	drItem := raw[0:6]
	drPriceStr := raw[6:13]
	drPctStr := raw[13:15]
	curRec.DrItem = drItem
	curRec.DrPrice = parsePrice(drPriceStr)
	curRec.DrPct = parseIntField(drPctStr, 2)
	hasRec = true
}

func PROCESS_PARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	rawDisc := curRec.DrPrice.Mul(decimal.New(curRec.DrPct, 0)).Shift(-2)
	rounded := rawDisc.Round(2)
	WsDiscount = storePIC(rounded, 5, 2)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	rawNet := curRec.DrPrice.Sub(WsDiscount)
	truncNet := rawNet.Truncate(2)
	WsNet = storePIC(truncNet, 5, 2)
	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	WsTotalNet = storePIC(sum, 8, 2)
	// ADD 1 TO WS-COUNT
	WsCount++
	if WsCount > 999 {
		WsCount = WsCount % 1000
	}
	WsPriceEd = formatEdited(curRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-ITEM is X(6) exactly 6 chars
	// DR-PCT is 9(2) zero-padded width 2
	pctStr := fmt.Sprintf("%02d", curRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", curRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	loadDiscFile()
	// MAIN-PARA
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}
